package org.apache.commons.lang;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.availableLocaleSet()
 * Designed to maximize branch and line coverage.
 */
public class LocaleUtils_availableLocaleSet_TriageGen0Test {

    /**
     * Resets the internal static cache 'cAvailableLocaleSet' using reflection
     * to allow testing both branches (null and non-null) of the method.
     */
    private void resetCache() throws Exception {
        Field field = LocaleUtils.class.getDeclaredField("cAvailableLocaleSet");
        field.setAccessible(true);
        field.set(null, null);
    }

    @Test
    public void testAvailableLocaleSet_FirstCall_InitializesSet() throws Exception {
        // Ensure the cache is null to trigger the 'if (set == null)' branch
        resetCache();

        Set result = LocaleUtils.availableLocaleSet();

        assertNotNull("The returned set should not be null", result);
        assertFalse("The returned set should not be empty", result.isEmpty());

        // Verify it is unmodifiable by attempting to modify it
        try {
            result.add(Locale.US);
            fail("Expected UnsupportedOperationException when modifying unmodifiable set");
        } catch (UnsupportedOperationException e) {
            // Success
        }
    }

    @Test
    public void testAvailableLocaleSet_SubsequentCalls_ReturnsSameInstance() throws Exception {
        // Initialize the cache
        resetCache();
        Set firstSet = LocaleUtils.availableLocaleSet();

        // Call again
        Set secondSet = LocaleUtils.availableLocaleSet();

        // Verify it returns the exact same instance (the cached set)
        assertSame("Subsequent calls should return the same cached instance", firstSet, secondSet);
    }

    @Test
    public void testAvailableLocaleSet_ContainsExpectedLocales() throws Exception {
        resetCache();
        Set locales = LocaleUtils.availableLocaleSet();

        // The availableLocaleList() is a dependency. 
        // We verify that the set contains at least one locale from the list.
        // This ensures the data flow from availableLocaleList() to the set is correct.
        boolean containsAtLeastOne = false;
        for (Locale locale : LocaleUtils.availableLocaleList()) {
            if (locales.contains(locale)) {
                containsAtLeastOne = true;
                break;
            }
        }
        assertTrue("The set should contain locales from the availableLocaleList", containsAtLeastOne);
    }
}
